// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Owned} from "../src/Owned.sol";

contract InvMutTest is Test {
    Owned c;
    function setUp() public { c = new Owned(); }
    function testFuzz_property(address caller, address newOwner) public {
        vm.assume(newOwner != address(0));

        address initialOwner = address(0);
        vm.prank(initialOwner);
        c.transferOwnership(address(1));

        assertTrue(c.owner() == address(1));

        bool ok;
        vm.prank(caller);
        try c.transferOwnership(newOwner) { ok = true; } catch { ok = false; }

        if (caller == address(1)) {
            assertTrue(ok && c.owner() == newOwner);
        } else {
            assertTrue(!ok && c.owner() == address(1));
        }
    }
}
